/* YoroOS 0.2.7 - Sprite icon renderer (all icons and UI glyphs are PNG-derived sprites)
 *
 * Uses 10.67x Lanczos-supersampled RGBA sprites (g_icon48_bgra & g_icon28_bgra)
 * generated by tools/mkassets.py + clean flat minimal utility symbols.
 * ZERO Windows 4-square logos anywhere in the OS.
 */
#include "kernel.h"

#include "assets_data.h"

extern const u32 g_icon48_bgra[ICON_SPRITE_COUNT][48 * 48];
extern const u32 g_icon28_bgra[ICON_SPRITE_COUNT][28 * 28];

enum {
    SPR_YORO        = 0,
    SPR_FILES       = 1,
    SPR_FOLDER      = 2,
    SPR_TRASH_EMPTY = 3,
    SPR_TRASH_FULL  = 4,
    SPR_BROWSER     = 5,
    SPR_STORE       = 6,
    SPR_TERMINAL    = 7,
    SPR_SETTINGS    = 8,
    SPR_INSTALLER   = 9,
    SPR_EXE         = 10,
    SPR_TXT         = 11,
    SPR_ZIP         = 12,
    SPR_MATRONIX    = 13,
    SPR_CHROME      = 14,
    SPR_FIREFOX     = 15,
    SPR_STEAM       = 16,
    SPR_PYTHON      = 17,
    SPR_VSCODE      = 18
};

u32 icon_id(const char *name) {
    if (!name) return ICON_APP;
    if (!strcasecmp(name, "folder") || !strcasecmp(name, "explorer")) return ICON_FOLDER;
    if (!strcasecmp(name, "terminal") || !strcasecmp(name, "cmd")) return ICON_TERMINAL;
    if (!strcasecmp(name, "settings")) return ICON_SETTINGS;
    if (!strcasecmp(name, "browser")) return ICON_BROWSER;
    if (!strcasecmp(name, "store")) return ICON_STORE;
    if (!strcasecmp(name, "steam")) return ICON_STEAM;
    if (!strcasecmp(name, "python")) return ICON_PYTHON;
    if (!strcasecmp(name, "vscode") || !strcasecmp(name, "code")) return ICON_VSCODE;
    if (!strcasecmp(name, "notepad")) return ICON_NOTEPAD;
    if (!strcasecmp(name, "calc")) return ICON_CALC;
    if (!strcasecmp(name, "computer") || !strcasecmp(name, "thispc")) return ICON_COMPUTER;
    if (!strcasecmp(name, "trash")) return ICON_TRASH;
    if (!strcasecmp(name, "matronix")) return ICON_MATRONIX;
    if (!strcasecmp(name, "chrome")) return ICON_CHROME;
    if (!strcasecmp(name, "firefox")) return ICON_FIREFOX;
    if (!strcasecmp(name, "git")) return ICON_GIT;
    if (!strcasecmp(name, "vlc")) return ICON_VLC;
    if (!strcasecmp(name, "discord")) return ICON_DISCORD;
    if (!strcasecmp(name, "paint")) return ICON_PAINT;
    if (!strcasecmp(name, "setup") || !strcasecmp(name, "installer")) return ICON_SETUP;
    if (!strcasecmp(name, "zip")) return ICON_ZIP;
    if (!strcasecmp(name, "exe")) return ICON_EXE;
    if (!strcasecmp(name, "taskmgr")) return ICON_TASKMGR;
    if (!strcasecmp(name, "regedit")) return ICON_REGEDIT;
    return ICON_APP;
}

void avatar_draw(int avatar_id, int x, int y, int s) {
    static const Color bg[6] = {
        {59, 130, 246, 255}, {16, 185, 129, 255}, {124, 58, 237, 255},
        {217, 119, 6, 255},  {14, 165, 233, 255}, {71, 85, 105, 255}
    };
    int cx = x + s / 2, cy = y + s / 2;
    fill_circle(cx, cy, s / 2, bg[avatar_id % 6]);
    fill_circle(cx, cy - s / 8, s / 5, C_WHITE);
    fill_round_rect((Rect){cx - s * 28 / 100, cy + s / 9, s * 56 / 100, s * 26 / 100}, s / 8, C_WHITE);
}

/* Bilinear alpha-blended sprite draw. tint == NULL keeps the sprite's own colours;
 * otherwise the sprite's alpha is used as a mask for the tint colour (UI glyphs). */
static void blit_bgra_sprite(const u32 *src, int sw, int x, int y, int dst_sz, const Color *tint) {
    int dx, dy;
    if (dst_sz <= 0) return;

    if (dst_sz == sw) {
        for (dy = 0; dy < sw; dy++) {
            for (dx = 0; dx < sw; dx++) {
                u32 p = src[dy * sw + dx];
                u8 a = (u8)(p >> 24);
                if (a == 0) continue;
                blend_px(x + dx, y + dy,
                         tint ? *tint : RGB((p >> 16) & 0xFFU, (p >> 8) & 0xFFU, p & 0xFFU), a);
            }
        }
        return;
    }

    for (dy = 0; dy < dst_sz; dy++) {
        int fy = (dy * (sw - 1) * 256) / (dst_sz > 1 ? (dst_sz - 1) : 1);
        int sy = fy >> 8, wy = fy & 255;
        int sy1 = sy + 1 < sw ? sy + 1 : sy;
        for (dx = 0; dx < dst_sz; dx++) {
            int fx = (dx * (sw - 1) * 256) / (dst_sz > 1 ? (dst_sz - 1) : 1);
            int sx = fx >> 8, wx = fx & 255;
            int sx1 = sx + 1 < sw ? sx + 1 : sx;
            u32 p00 = src[sy * sw + sx],   p10 = src[sy * sw + sx1];
            u32 p01 = src[sy1 * sw + sx],  p11 = src[sy1 * sw + sx1];
            u32 w00 = (u32)(256 - wx) * (u32)(256 - wy);
            u32 w10 = (u32)wx         * (u32)(256 - wy);
            u32 w01 = (u32)(256 - wx) * (u32)wy;
            u32 w11 = (u32)wx         * (u32)wy;
            u8 a = (u8)((((p00 >> 24) & 255U) * w00 + ((p10 >> 24) & 255U) * w10 +
                         ((p01 >> 24) & 255U) * w01 + ((p11 >> 24) & 255U) * w11) >> 16);
            if (a < 4) continue;
            if (tint) {
                blend_px(x + dx, y + dy, *tint, a);
            } else {
                u8 r = (u8)((((p00 >> 16) & 255U) * w00 + ((p10 >> 16) & 255U) * w10 +
                             ((p01 >> 16) & 255U) * w01 + ((p11 >> 16) & 255U) * w11) >> 16);
                u8 g = (u8)((((p00 >> 8) & 255U) * w00 + ((p10 >> 8) & 255U) * w10 +
                             ((p01 >> 8) & 255U) * w01 + ((p11 >> 8) & 255U) * w11) >> 16);
                u8 b = (u8)(((p00 & 255U) * w00 + (p10 & 255U) * w10 +
                             (p01 & 255U) * w01 + (p11 & 255U) * w11) >> 16);
                blend_px(x + dx, y + dy, RGB(r, g, b), a);
            }
        }
    }
}

static void draw_sprite(int spr_id, int x, int y, int s) {
    if (s <= 30)
        blit_bgra_sprite(g_icon28_bgra[spr_id], 28, x, y, s, NULL);
    else
        blit_bgra_sprite(g_icon48_bgra[spr_id], 48, x, y, s, NULL);
}

static void draw_glyph(int spr_id, int x, int y, int s, Color tint) {
    if (s <= 30)
        blit_bgra_sprite(g_icon28_bgra[spr_id], 28, x, y, s, &tint);
    else
        blit_bgra_sprite(g_icon48_bgra[spr_id], 48, x, y, s, &tint);
}

/* Glyph colour for app-style glyphs on the desktop / taskbar (#F8FAFC) */
#define GLYPH_WHITE RGB(248, 250, 252)

void icon_draw(u32 id, int x, int y, int s) {
    switch (id) {
    case ICON_COMPUTER:
    case ICON_DRIVE:        draw_sprite(SPR_FILES, x, y, s); break;
    case ICON_FOLDER:       draw_sprite(SPR_FOLDER, x, y, s); break;
    case ICON_TRASH_EMPTY:  draw_sprite(SPR_TRASH_EMPTY, x, y, s); break;
    case ICON_TRASH:        draw_sprite(SPR_TRASH_FULL, x, y, s); break;
    case ICON_BROWSER:      draw_sprite(SPR_BROWSER, x, y, s); break;
    case ICON_STORE:        draw_sprite(SPR_STORE, x, y, s); break;
    case ICON_TERMINAL:     draw_sprite(SPR_TERMINAL, x, y, s); break;
    case ICON_SETTINGS:     draw_sprite(SPR_SETTINGS, x, y, s); break;
    case ICON_SETUP:
    case ICON_RESTORE:      draw_sprite(SPR_INSTALLER, x, y, s); break;
    case ICON_EXE:
    case ICON_APP:          draw_sprite(SPR_EXE, x, y, s); break;
    case ICON_NOTEPAD:
    case ICON_TEXTFILE:
    case ICON_CODEFILE:     draw_sprite(SPR_TXT, x, y, s); break;
    case ICON_ZIP:          draw_sprite(SPR_ZIP, x, y, s); break;
    case ICON_MATRONIX:     draw_sprite(SPR_MATRONIX, x, y, s); break;
    case ICON_CHROME:       draw_sprite(SPR_CHROME, x, y, s); break;
    case ICON_FIREFOX:      draw_sprite(SPR_FIREFOX, x, y, s); break;
    case ICON_STEAM:        draw_sprite(SPR_STEAM, x, y, s); break;
    case ICON_PYTHON:       draw_sprite(SPR_PYTHON, x, y, s); break;
    case ICON_VSCODE:       draw_sprite(SPR_VSCODE, x, y, s); break;
    case ICON_ABOUT:
    case ICON_SHIELD:       draw_sprite(SPR_YORO, x, y, s); break;

    /* UI and app glyphs: Lucide outlines rendered to sprites in assets/icons/glyphs */
    case ICON_CALC:         draw_glyph(SPR_G_CALC, x, y, s, GLYPH_WHITE); break;
    case ICON_IMAGE:        draw_glyph(SPR_G_IMAGE, x, y, s, GLYPH_WHITE); break;
    case ICON_PAINT:        draw_glyph(SPR_G_PAINT, x, y, s, GLYPH_WHITE); break;
    case ICON_GIT:          draw_glyph(SPR_G_GIT, x, y, s, GLYPH_WHITE); break;
    case ICON_VLC:          draw_glyph(SPR_G_VLC, x, y, s, GLYPH_WHITE); break;
    case ICON_DISCORD:      draw_glyph(SPR_G_DISCORD, x, y, s, GLYPH_WHITE); break;
    case ICON_TASKMGR:      draw_glyph(SPR_G_TASKMGR, x, y, s, GLYPH_WHITE); break;
    case ICON_REGEDIT:      draw_glyph(SPR_G_REGEDIT, x, y, s, GLYPH_WHITE); break;
    case ICON_POWER:        draw_glyph(SPR_G_POWER, x, y, s, RGB(248, 113, 113)); break;
    case ICON_SEARCH:       draw_glyph(SPR_G_SEARCH, x, y, s, theme->text_main); break;
    case ICON_WIFI:         draw_glyph(SPR_G_WIFI, x, y, s, theme->text_main); break;
    case ICON_VOLUME:       draw_glyph(SPR_G_VOLUME, x, y, s, theme->text_main); break;
    case ICON_BELL:         draw_glyph(SPR_G_BELL, x, y, s, theme->text_main); break;
    case ICON_UP:           draw_glyph(SPR_G_UP, x, y, s, theme->text_main); break;
    case ICON_BACK:         draw_glyph(SPR_G_BACK, x, y, s, theme->text_main); break;
    case ICON_PLUS:         draw_glyph(SPR_G_PLUS, x, y, s, theme->text_main); break;
    case ICON_DOWNLOAD:     draw_glyph(SPR_G_DOWNLOAD, x, y, s, RGB(56, 189, 248)); break;
    case ICON_ARROW_DOWN:   draw_glyph(SPR_G_ARROW_DOWN, x, y, s, RGB(56, 189, 248)); break;
    case ICON_CHECK:        draw_glyph(SPR_G_CHECK, x, y, s, RGB(16, 185, 129)); break;

    default:
        draw_sprite(SPR_YORO, x, y, s);
        break;
    }
}
